//! The OCL standard library for code generated by Oxychloride: object handles, errors
//! (`invalid`), and the operations on numbers, strings and collections that the translated
//! OCL calls.
//!
//! Copied verbatim into every generated crate; do not edit. Collections are `Vec`s (their
//! kind is known when the code is generated); they never contain null.

#![allow(dead_code)]

use std::fmt;

/// Identifies an object of a `Model`.
#[derive(Copy, Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct ObjectId(pub u32);

impl ObjectId {
    pub fn index(self) -> usize {
        self.0 as usize
    }
}

/// A typed handle of an object (`Book`, `Member`, …): a copyable wrapper of its
/// [`ObjectId`]. Handles of a class may refer to objects of its subclasses.
pub trait Handle: Copy + Eq + std::hash::Hash + fmt::Debug {
    /// The class index (see `CLASSES`) the handle type stands for.
    const CLASS: usize;
    fn e_id(self) -> ObjectId;
    /// A handle for `id`, unchecked: `id` must be an object of a conforming class.
    fn from_e_id(id: ObjectId) -> Self;
}

impl Handle for ObjectId {
    const CLASS: usize = usize::MAX;
    fn e_id(self) -> ObjectId {
        self
    }
    fn from_e_id(id: ObjectId) -> Self {
        id
    }
}

/// Converts between handle types (upcasts, and downcasts already checked).
pub fn recast<T: Handle, U: Handle>(u: U) -> T {
    T::from_e_id(u.e_id())
}

/// Converts a collection of handles.
pub fn recast_all<T: Handle, U: Handle>(items: Vec<U>) -> Vec<T> {
    items.into_iter().map(recast).collect()
}

/// A pre- or postcondition that does not hold at an operation call.
#[derive(Clone, Debug, PartialEq)]
pub struct ContractViolation {
    /// `"precondition"` or `"postcondition"`.
    pub kind: &'static str,
    /// `Class::operation()`.
    pub operation: &'static str,
    pub constraint: &'static str,
    pub object: ObjectId,
    /// The object's label (e.g. `Book 'Dune'`).
    pub label: String,
    /// False when the condition could not be evaluated (`message` says why).
    pub violated: bool,
    pub message: Option<String>,
}

/// Why an OCL expression has no value.
#[derive(Clone, Debug, PartialEq)]
pub enum Error {
    /// OCL `invalid`: null navigation, an index out of range, division by zero, …
    Invalid(String),
    /// A pre- or postcondition of a called operation failed.
    Contract(Box<ContractViolation>),
}

pub type Result<T> = std::result::Result<T, Error>;

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Invalid(m) => write!(f, "invalid: {m}"),
            Error::Contract(c) => {
                write!(
                    f,
                    "{} {} of {} {} on {}",
                    c.kind,
                    c.constraint,
                    c.operation,
                    if c.violated { "is violated" } else { "failed" },
                    c.label
                )?;
                if let Some(m) = &c.message {
                    write!(f, ": {m}")?;
                }
                Ok(())
            }
        }
    }
}

impl std::error::Error for Error {}

/// OCL `invalid`.
pub fn invalid<T>(reason: impl Into<String>) -> Result<T> {
    Err(Error::Invalid(reason.into()))
}

/// The value of a non-null `Option`, or invalid ("<what> is null").
pub fn some<T>(value: Option<T>, what: &str) -> Result<T> {
    value.ok_or_else(|| Error::Invalid(format!("{what} is null")))
}

/// Evaluates a pre- or postcondition: `Ok` if it holds, otherwise the violation (with the
/// message, for violated conditions that have one).
#[allow(clippy::too_many_arguments)]
pub fn check_condition(
    kind: &'static str,
    operation: &'static str,
    constraint: &'static str,
    object: ObjectId,
    label: impl FnOnce() -> String,
    value: Result<bool>,
    message: impl FnOnce() -> Result<String>,
) -> Result<()> {
    let (violated, message) = match value {
        Ok(true) => return Ok(()),
        Ok(false) => (true, message().ok()),
        Err(Error::Invalid(m)) => (false, Some(format!("evaluated to invalid: {m}"))),
        Err(e) => (false, Some(e.to_string())),
    };
    Err(Error::Contract(Box::new(ContractViolation {
        kind,
        operation,
        constraint,
        object,
        label: label(),
        violated,
        message,
    })))
}

/// `oclIsUndefined()` of an expression that may fail.
pub fn is_undefined<T>(value: impl FnOnce() -> Result<Option<T>>) -> bool {
    !matches!(value(), Ok(Some(_)))
}

/// `oclIsInvalid()`.
pub fn is_invalid<T>(value: impl FnOnce() -> Result<T>) -> bool {
    value().is_err()
}

// ------------------------------------------------------------------ numbers

pub fn add(a: i64, b: i64) -> Result<i64> {
    a.checked_add(b).ok_or_else(|| Error::Invalid("integer overflow".into()))
}

pub fn sub(a: i64, b: i64) -> Result<i64> {
    a.checked_sub(b).ok_or_else(|| Error::Invalid("integer overflow".into()))
}

pub fn mul(a: i64, b: i64) -> Result<i64> {
    a.checked_mul(b).ok_or_else(|| Error::Invalid("integer overflow".into()))
}

pub fn neg(a: i64) -> Result<i64> {
    a.checked_neg().ok_or_else(|| Error::Invalid("integer overflow".into()))
}

/// `/`: always a Real.
pub fn divide(a: f64, b: f64) -> Result<f64> {
    if b == 0.0 { invalid("division by zero") } else { Ok(a / b) }
}

/// `div`: integer division truncating toward zero.
pub fn div(a: i64, b: i64) -> Result<i64> {
    if b == 0 { invalid("division by zero") } else { Ok(a.wrapping_div(b)) }
}

/// `mod`: the remainder of `div`.
pub fn modulo(a: i64, b: i64) -> Result<i64> {
    if b == 0 { invalid("division by zero") } else { Ok(a.wrapping_rem(b)) }
}

pub fn abs(a: i64) -> Result<i64> {
    a.checked_abs().ok_or_else(|| Error::Invalid("integer overflow".into()))
}

/// A Real as an Integer (after `floor`, `round` or truncation).
pub fn real_to_int(r: f64) -> Result<i64> {
    if r.is_finite() && r.abs() < 9.2e18 { Ok(r as i64) } else { invalid("number out of Integer range") }
}

pub fn floor(r: f64) -> Result<i64> {
    real_to_int(r.floor())
}

pub fn round(r: f64) -> Result<i64> {
    real_to_int((r + 0.5).floor())
}

pub fn max_real(a: f64, b: f64) -> f64 {
    if a >= b { a } else { b }
}

pub fn min_real(a: f64, b: f64) -> f64 {
    if a <= b { a } else { b }
}

/// OCL's text of a Real: `1.0`, `2.5`, `1e300`.
pub fn format_real(r: f64) -> String {
    if r.is_finite() && r.fract() == 0.0 && r.abs() < 1e16 { format!("{r:.1}") } else { format!("{r}") }
}

/// `toString()` of the values the generated code renders without a model.
pub trait OclString {
    fn ocl_string(&self) -> String;
}

impl OclString for bool {
    fn ocl_string(&self) -> String {
        self.to_string()
    }
}

impl OclString for i64 {
    fn ocl_string(&self) -> String {
        self.to_string()
    }
}

impl OclString for f64 {
    fn ocl_string(&self) -> String {
        format_real(*self)
    }
}

impl OclString for String {
    fn ocl_string(&self) -> String {
        self.clone()
    }
}

impl<T: OclString> OclString for Option<T> {
    fn ocl_string(&self) -> String {
        self.as_ref().map_or_else(|| "null".to_string(), OclString::ocl_string)
    }
}

/// Renders a collection as `Kind{a, b}` (strings quoted).
pub fn render_collection<T>(kind: &str, items: &[T], render: impl Fn(&T) -> String) -> String {
    format!("{kind}{{{}}}", items.iter().map(render).collect::<Vec<_>>().join(", "))
}

/// A string in OCL literal syntax.
pub fn quote(s: &str) -> String {
    let mut out = String::from("'");
    for c in s.chars() {
        match c {
            '\'' => out.push_str("\\'"),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out.push('\'');
    out
}

// ------------------------------------------------------------------ strings (1-based)

pub fn str_size(s: &str) -> i64 {
    s.chars().count() as i64
}

pub fn substring(s: &str, lower: i64, upper: i64) -> Result<String> {
    let chars: Vec<char> = s.chars().collect();
    if lower < 1 || upper < lower - 1 || upper as usize > chars.len() {
        return invalid(format!("substring({lower}, {upper}) out of range for a string of size {}", chars.len()));
    }
    Ok(chars[lower as usize - 1..upper as usize].iter().collect())
}

pub fn str_to_integer(s: &str) -> Result<i64> {
    s.trim().parse().map_err(|_| Error::Invalid(format!("'{s}' is not an integer")))
}

pub fn str_to_real(s: &str) -> Result<f64> {
    s.trim().parse().map_err(|_| Error::Invalid(format!("'{s}' is not a number")))
}

pub fn str_to_boolean(s: &str) -> Result<bool> {
    match s.trim() {
        "true" => Ok(true),
        "false" => Ok(false),
        _ => invalid(format!("'{s}' is not a Boolean")),
    }
}

pub fn str_index_of(s: &str, sub: &str) -> i64 {
    s.find(sub).map_or(0, |b| s[..b].chars().count() as i64 + 1)
}

pub fn str_last_index_of(s: &str, sub: &str) -> i64 {
    s.rfind(sub).map_or(0, |b| s[..b].chars().count() as i64 + 1)
}

pub fn str_at(s: &str, i: i64) -> Result<String> {
    match s.chars().nth((i as usize).wrapping_sub(1)) {
        Some(c) if i >= 1 => Ok(c.to_string()),
        _ => invalid(format!("index {i} out of range")),
    }
}

pub fn characters(s: &str) -> Vec<String> {
    s.chars().map(|c| c.to_string()).collect()
}

pub fn equals_ignore_case(a: &str, b: &str) -> bool {
    a.to_lowercase() == b.to_lowercase()
}

pub fn tokenize(s: &str, delimiters: &str, keep: bool) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    for c in s.chars() {
        if delimiters.contains(c) {
            if !cur.is_empty() {
                out.push(std::mem::take(&mut cur));
            }
            if keep {
                out.push(c.to_string());
            }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

/// The default delimiters of `tokenize()`.
pub const WHITESPACE: &str = " \t\n\r\u{c}";

// ------------------------------------------------------------------ collections

/// The items without duplicates (first occurrences kept).
pub fn unique<T: PartialEq>(items: Vec<T>) -> Vec<T> {
    let mut out: Vec<T> = Vec::with_capacity(items.len());
    for i in items {
        if !out.contains(&i) {
            out.push(i);
        }
    }
    out
}

pub fn count<T: PartialEq>(items: &[T], x: &T) -> i64 {
    items.iter().filter(|i| *i == x).count() as i64
}

pub fn includes_all<T: PartialEq>(items: &[T], other: &[T]) -> bool {
    other.iter().all(|o| items.contains(o))
}

pub fn excludes_all<T: PartialEq>(items: &[T], other: &[T]) -> bool {
    other.iter().all(|o| !items.contains(o))
}

pub fn sum_int(items: &[i64]) -> Result<i64> {
    items.iter().try_fold(0i64, |acc, i| add(acc, *i))
}

pub fn sum_real(items: &[f64]) -> f64 {
    items.iter().sum()
}

pub fn max<T: PartialOrd + Clone>(items: &[T]) -> Result<T> {
    let mut best: Option<&T> = None;
    for i in items {
        match best {
            None => best = Some(i),
            Some(b) => match i.partial_cmp(b) {
                Some(std::cmp::Ordering::Greater) => best = Some(i),
                Some(_) => {}
                None => return invalid("max() requires comparable elements"),
            },
        }
    }
    best.cloned().ok_or_else(|| Error::Invalid("max() of an empty collection".into()))
}

pub fn min<T: PartialOrd + Clone>(items: &[T]) -> Result<T> {
    let mut best: Option<&T> = None;
    for i in items {
        match best {
            None => best = Some(i),
            Some(b) => match i.partial_cmp(b) {
                Some(std::cmp::Ordering::Less) => best = Some(i),
                Some(_) => {}
                None => return invalid("min() requires comparable elements"),
            },
        }
    }
    best.cloned().ok_or_else(|| Error::Invalid("min() of an empty collection".into()))
}

pub fn including<T: PartialEq>(mut items: Vec<T>, x: T, unique_kind: bool) -> Vec<T> {
    if !unique_kind || !items.contains(&x) {
        items.push(x);
    }
    items
}

pub fn excluding<T: PartialEq>(items: Vec<T>, x: &T) -> Vec<T> {
    items.into_iter().filter(|i| i != x).collect()
}

pub fn including_all<T: PartialEq>(mut items: Vec<T>, other: Vec<T>, unique_kind: bool) -> Vec<T> {
    for o in other {
        if !unique_kind || !items.contains(&o) {
            items.push(o);
        }
    }
    items
}

pub fn excluding_all<T: PartialEq>(items: Vec<T>, other: &[T]) -> Vec<T> {
    items.into_iter().filter(|i| !other.contains(i)).collect()
}

pub fn intersection<T: PartialEq>(items: Vec<T>, other: Vec<T>, bag: bool) -> Vec<T> {
    if !bag {
        return unique(items.into_iter().filter(|i| other.contains(i)).collect());
    }
    let mut remaining = other;
    let mut out = Vec::new();
    for i in items {
        if let Some(p) = remaining.iter().position(|o| *o == i) {
            remaining.remove(p);
            out.push(i);
        }
    }
    out
}

pub fn symmetric_difference<T: PartialEq + Clone>(items: Vec<T>, other: Vec<T>) -> Vec<T> {
    let mut out: Vec<T> = items.iter().filter(|i| !other.contains(i)).cloned().collect();
    out.extend(other.iter().filter(|o| !items.contains(o)).cloned());
    unique(out)
}

pub fn append<T: PartialEq>(items: Vec<T>, x: T, unique_kind: bool) -> Vec<T> {
    let mut out: Vec<T> = if unique_kind { items.into_iter().filter(|i| *i != x).collect() } else { items };
    out.push(x);
    out
}

pub fn prepend<T: PartialEq>(items: Vec<T>, x: T, unique_kind: bool) -> Vec<T> {
    let mut out: Vec<T> = if unique_kind { items.into_iter().filter(|i| *i != x).collect() } else { items };
    out.insert(0, x);
    out
}

pub fn insert_at<T: PartialEq>(items: Vec<T>, index: i64, x: T, unique_kind: bool) -> Result<Vec<T>> {
    let mut out: Vec<T> = if unique_kind { items.into_iter().filter(|i| *i != x).collect() } else { items };
    if index < 1 || index as usize > out.len() + 1 {
        return invalid(format!("index {index} out of range"));
    }
    out.insert(index as usize - 1, x);
    Ok(out)
}

pub fn at<T: Clone>(items: &[T], i: i64) -> Result<T> {
    if i < 1 || i as usize > items.len() {
        return invalid(format!("index {i} out of range 1..{}", items.len()));
    }
    Ok(items[i as usize - 1].clone())
}

pub fn first<T: Clone>(items: &[T]) -> Result<T> {
    items.first().cloned().ok_or_else(|| Error::Invalid("first() of an empty collection".into()))
}

pub fn last<T: Clone>(items: &[T]) -> Result<T> {
    items.last().cloned().ok_or_else(|| Error::Invalid("last() of an empty collection".into()))
}

pub fn index_of<T: PartialEq>(items: &[T], x: &T) -> Result<i64> {
    match items.iter().position(|i| i == x) {
        Some(p) => Ok(p as i64 + 1),
        None => invalid("indexOf(): element not found"),
    }
}

pub fn sub_sequence<T: Clone>(items: &[T], lower: i64, upper: i64) -> Result<Vec<T>> {
    if lower < 1 || upper as usize > items.len() || lower > upper {
        return invalid("subSequence(): indices out of range");
    }
    Ok(items[lower as usize - 1..upper as usize].to_vec())
}

pub fn reverse<T>(mut items: Vec<T>) -> Vec<T> {
    items.reverse();
    items
}

/// `product`: all pairs, as `Tuple(first, second)`.
pub fn product<A: Clone, B: Clone>(items: &[A], other: &[B]) -> Vec<(Option<A>, Option<B>)> {
    items.iter().flat_map(|a| other.iter().map(move |b| (Some(a.clone()), Some(b.clone())))).collect()
}

/// `a - b` for collections.
pub fn difference<T: PartialEq>(items: Vec<T>, other: &[T]) -> Vec<T> {
    items.into_iter().filter(|i| !other.contains(i)).collect()
}

/// `=` for Sets (and OrderedSets compared as sets).
pub fn set_eq<T: PartialEq>(a: &[T], b: &[T]) -> bool {
    a.iter().all(|x| b.contains(x)) && b.iter().all(|y| a.contains(y))
}

/// `=` for Bags.
pub fn bag_eq<T: PartialEq>(a: &[T], b: &[T]) -> bool {
    a.len() == b.len() && a.iter().all(|x| count(a, x) == count(b, x))
}

/// `first..last`.
pub fn range(first: i64, last: i64) -> Result<Vec<i64>> {
    if last.saturating_sub(first) > 10_000_000 {
        return invalid("range is too large");
    }
    Ok((first..=last).collect())
}

// ------------------------------------------------------------------ iterators

pub fn select<T: Clone>(items: Vec<T>, mut body: impl FnMut(T) -> Result<bool>) -> Result<Vec<T>> {
    let mut out = Vec::new();
    for i in items {
        if body(i.clone())? {
            out.push(i);
        }
    }
    Ok(out)
}

pub fn reject<T: Clone>(items: Vec<T>, mut body: impl FnMut(T) -> Result<bool>) -> Result<Vec<T>> {
    let mut out = Vec::new();
    for i in items {
        if !body(i.clone())? {
            out.push(i);
        }
    }
    Ok(out)
}

pub fn collect<T, U>(items: Vec<T>, body: impl FnMut(T) -> Result<U>) -> Result<Vec<U>> {
    items.into_iter().map(body).collect()
}

/// `collect` with a collection-valued body: the results are flattened.
pub fn collect_flat<T, U>(items: Vec<T>, mut body: impl FnMut(T) -> Result<Vec<U>>) -> Result<Vec<U>> {
    let mut out = Vec::new();
    for i in items {
        out.extend(body(i)?);
    }
    Ok(out)
}

/// `collect` with a body that may be null: nulls are left out.
pub fn collect_some<T, U>(items: Vec<T>, mut body: impl FnMut(T) -> Result<Option<U>>) -> Result<Vec<U>> {
    let mut out = Vec::new();
    for i in items {
        out.extend(body(i)?);
    }
    Ok(out)
}

/// `forAll`: false if the body is false for some element, else invalid if it failed for
/// one, else true.
pub fn for_all<T>(items: Vec<T>, mut body: impl FnMut(T) -> Result<bool>) -> Result<bool> {
    let mut error = None;
    for i in items {
        match body(i) {
            Ok(false) => return Ok(false),
            Ok(true) => {}
            Err(e) => error = Some(e),
        }
    }
    error.map_or(Ok(true), Err)
}

/// `exists`: true if the body is true for some element, else invalid if it failed for one,
/// else false.
pub fn exists<T>(items: Vec<T>, mut body: impl FnMut(T) -> Result<bool>) -> Result<bool> {
    let mut error = None;
    for i in items {
        match body(i) {
            Ok(true) => return Ok(true),
            Ok(false) => {}
            Err(e) => error = Some(e),
        }
    }
    error.map_or(Ok(false), Err)
}

pub fn one<T>(items: Vec<T>, mut body: impl FnMut(T) -> Result<bool>) -> Result<bool> {
    let mut n = 0;
    for i in items {
        if body(i)? {
            n += 1;
        }
    }
    Ok(n == 1)
}

/// `any`: the first element for which the body holds.
pub fn any<T: Clone>(items: Vec<T>, mut body: impl FnMut(T) -> Result<bool>) -> Result<Option<T>> {
    for i in items {
        if body(i.clone())? {
            return Ok(Some(i));
        }
    }
    Ok(None)
}

pub fn is_unique<T, K: PartialEq>(items: Vec<T>, mut key: impl FnMut(T) -> Result<K>) -> Result<bool> {
    let mut seen: Vec<K> = Vec::new();
    for i in items {
        let k = key(i)?;
        if seen.contains(&k) {
            return Ok(false);
        }
        seen.push(k);
    }
    Ok(true)
}

pub fn sorted_by<T: Clone, K: PartialOrd>(items: Vec<T>, mut key: impl FnMut(T) -> Result<K>) -> Result<Vec<T>> {
    let mut keyed = Vec::with_capacity(items.len());
    for i in items {
        keyed.push((key(i.clone())?, i));
    }
    let mut failed = false;
    keyed.sort_by(|a, b| {
        a.0.partial_cmp(&b.0).unwrap_or_else(|| {
            failed = true;
            std::cmp::Ordering::Equal
        })
    });
    if failed {
        return invalid("sortedBy: keys are not comparable");
    }
    Ok(keyed.into_iter().map(|(_, v)| v).collect())
}

/// The transitive closure of `body` from `items` (without duplicates, breadth first).
pub fn closure<T: Clone + PartialEq>(items: Vec<T>, mut body: impl FnMut(T) -> Result<Vec<T>>) -> Result<Vec<T>> {
    let mut out: Vec<T> = Vec::new();
    let mut queue: std::collections::VecDeque<T> = items.into_iter().collect();
    while let Some(i) = queue.pop_front() {
        for n in body(i)? {
            if !out.contains(&n) {
                out.push(n.clone());
                queue.push_back(n);
            }
        }
    }
    Ok(out)
}
